create table public.submission_drafts (id uuid primary key default gen_random_uuid(), submission_type text not null check (submission_type in ('contact_messages','quote_requests','job_applications')), submission_id uuid, staff_id uuid not null, summary text not null, reply text not null, created_at timestamptz not null default now());
grant select, insert, update, delete on public.submission_drafts to authenticated;
grant all on public.submission_drafts to service_role;
alter table public.submission_drafts enable row level security;
create policy "staff draft access" on public.submission_drafts for all to authenticated using (public.is_staff(auth.uid())) with check (public.is_staff(auth.uid()) and staff_id = auth.uid());
create table public.ai_access_state (id boolean primary key default true check (id), blocked boolean not null default false, reason text, updated_at timestamptz not null default now());
grant select on public.ai_access_state to authenticated;
grant all on public.ai_access_state to service_role;
alter table public.ai_access_state enable row level security;
create policy "staff see AI status" on public.ai_access_state for select to authenticated using (public.is_staff(auth.uid()));
alter table public.clients add column if not exists is_demo boolean not null default false;
alter table public.contact_messages add column if not exists is_demo boolean not null default false;
alter table public.quote_requests add column if not exists is_demo boolean not null default false;
alter table public.job_applications add column if not exists is_demo boolean not null default false;
create policy "staff update contact submissions" on public.contact_messages for update to authenticated using (public.is_staff(auth.uid())) with check (public.is_staff(auth.uid()));
create policy "staff update quote submissions" on public.quote_requests for update to authenticated using (public.is_staff(auth.uid())) with check (public.is_staff(auth.uid()));
create policy "staff update job submissions" on public.job_applications for update to authenticated using (public.is_staff(auth.uid())) with check (public.is_staff(auth.uid()));
create policy "staff read unpublished services" on public.services for select to authenticated using (public.is_staff(auth.uid()));
alter policy "public read services" on public.services using (published);
create policy "staff read unpublished industries" on public.industries for select to authenticated using (public.is_staff(auth.uid()));
alter policy "public read industries" on public.industries using (published);
create policy "staff read unpublished technologies" on public.technologies for select to authenticated using (public.is_staff(auth.uid()));
alter policy "public read technologies" on public.technologies using (published);
create policy "staff read unpublished portfolio" on public.portfolio_projects for select to authenticated using (public.is_staff(auth.uid()));
alter policy "public read portfolio_projects" on public.portfolio_projects using (published);
create policy "staff read unpublished products" on public.saas_products for select to authenticated using (public.is_staff(auth.uid()));
alter policy "public read saas_products" on public.saas_products using (published);
create policy "staff read unpublished blog" on public.blog_posts for select to authenticated using (public.is_staff(auth.uid()));
alter policy "public read blog_posts" on public.blog_posts using (published);
create policy "staff read unpublished team" on public.team_members for select to authenticated using (public.is_staff(auth.uid()));
alter policy "public read team_members" on public.team_members using (published);
create policy "staff read unpublished testimonials" on public.testimonials for select to authenticated using (public.is_staff(auth.uid()));
alter policy "public read testimonials" on public.testimonials using (published);
create policy "staff read unpublished faqs" on public.faqs for select to authenticated using (public.is_staff(auth.uid()));
alter policy "public read faqs" on public.faqs using (published);
create policy "staff read closed jobs" on public.job_openings for select to authenticated using (public.is_staff(auth.uid()));
alter policy "public read job_openings" on public.job_openings using (status = 'Open');
create policy "staff upload project files" on storage.objects for insert to authenticated with check (bucket_id = 'project-files' and public.is_staff(auth.uid()));
create policy "staff manage project files" on storage.objects for all to authenticated using (bucket_id = 'project-files' and public.is_staff(auth.uid())) with check (bucket_id = 'project-files' and public.is_staff(auth.uid()));
create policy "client read visible project files" on storage.objects for select to authenticated using (bucket_id = 'project-files' and exists (select 1 from public.project_documents d where d.file_path = name and d.visible_to_client and public.owns_project(d.project_id)));
alter table public.client_projects add constraint project_progress_range check (progress between 0 and 100) not valid;
alter table public.support_tickets add constraint ticket_project_owned check (project_id is null or public.owns_project(project_id) or public.is_staff(auth.uid())) not valid;